def transfer(from_acc, to_acc, amount):
    if amount < 0:
        raise ValueError("amount must be non-negative")

    with db.transaction():
        balances = {}
        for account_id in sorted({from_acc, to_acc}):
            balances[account_id] = db.query(
                "SELECT balance FROM accounts WHERE id = ? FOR UPDATE",
                account_id,
            )

        if balances[from_acc] is None or balances[to_acc] is None:
            raise ValueError("account not found")
        if balances[from_acc] < amount:
            return False
        if from_acc == to_acc or amount == 0:
            return True

        db.execute(
            "UPDATE accounts SET balance = balance - ? WHERE id = ?",
            amount,
            from_acc,
        )
        db.execute(
            "UPDATE accounts SET balance = balance + ? WHERE id = ?",
            amount,
            to_acc,
        )
        return True
